Method.Source:
/// <summary>
/// CoC extension
/// </summary>
/// <param name = "_callerTableId">_callerTableId</param>
/// <param name = "_callerRecord">_callerRecord</param>
void initFromCaller(TableId _callerTableId, Common _callerRecord)
{
    next initFromCaller(_callerTableId, _callerRecord);
 
    switch(_callerTableId)
    {
        // MPJ-26540
        case tableNum(RetailPricingSimulatorSalesTransaction):
            this.TransTableId   = _callerRecord.TableID;
            this.TransRecId     = _callerRecord.RecId;
            break;
    }
}

    /// <summary>
    /// CoC extension to initialise the tax item group from the purch line
    /// </summary>
    /// <param name = "purchLine">purchase line</param>
    void initFromPurchLine(PurchLine purchLine)
    {
        MarkupTable markupTable;

        next initFromPurchLine(purchLine);

        if (!this.TaxItemGroup)
        {
            this.TaxItemGroup = purchLine.TaxItemGroup;
        }
    }

    /// <summary>
    /// CoC extension to initialise the tax item group from the pending vendor invoice line
    /// </summary>
    /// <param name = "_vendInvoiceInfoLine">invoice line</param>
    public void initFromVendInvoiceInfoLine(VendInvoiceInfoLine _vendInvoiceInfoLine)
    {
        next initFromVendInvoiceInfoLine(_vendInvoiceInfoLine);

        if (!this.TaxItemGroup)
        {
            this.TaxItemGroup = _vendInvoiceInfoLine.TaxItemGroup;
        }
    }

    /// <summary>
    /// CB326_HeaderChargesTotalCases
    /// Fixing a bug. shouldn't use initFromMarkupTable to retrieve the auto charges from the charge code as a charge code could be configured under many auto charges.
    /// Instead this should be done under initFromMarkupAutoLine().
    /// </summary>
    /// <param name = "markupAutoLine">Auto charge line</param>
    void initFromMarkupAutoLine(MarkupAutoLine  markupAutoLine)
    {
        next initFromMarkupAutoLine(markupAutoLine);

        MarkupAutoTable markupAutoTable;

        select firstonly METAdvancedCalculation, RecId from markupAutoTable
                where markupAutoTable.RecId == markupAutoLine.TableRecId;

        if (markupAutoTable.METAdvancedCalculation)
        {
            this.METAdvancedCalculation      =   markupAutoTable.METAdvancedCalculation;
            this.METChargesMethod   =   markupAutoLine.METChargesMethod;
        }
        else
        {
            this.METChargesMethod   =   METChargesMethod::None;
        }
    }

    /// <summary>
    /// COC of init value method to assign default value
    /// </summary>
    void initValue()
    {
        next initvalue();

        this.METChargesMethod = METChargesMethod::None;
    }

    /// <summary>
    /// Modified method COC
    /// </summary>
    /// <param name = "_fieldId">FieldID reference</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(MarkupTrans, METAdvancedCalculation):

                if (this.METAdvancedCalculation == NoYes::No)
                {
                    this.METChargesMethod = METChargesMethod::None;
                }
                else
                {
                    MarkupAutoTable markupAutoTable;
                    MarkupAutoLine  markupAutoLine;

                    select firstonly METChargesMethod, RecId, TableRecId from markupAutoLine
                        where markupAutoLine.MarkupCode == this.MarkupCode  &&
                            markupAutoLine.ModuleType == this.ModuleType
                        join METAdvancedCalculation, RecId from markupAutoTable
                            where markupAutoTable.RecId == markupAutoLine.TableRecId ;

                    if (markupAutoTable.METAdvancedCalculation && markupAutoLine.METChargesMethod != METChargesMethod::None)
                    {
                        this.METChargesMethod   =   markupAutoLine.METChargesMethod;
                    }
                    else
                    {
                        this.METChargesMethod   =   METChargesMethod::Weight;
                    }
                }

                break;
        }
    }

    /// <summary>
    /// Validates write.
    /// </summary>
    /// <returns>
    /// Returns true if the record passes validation; otherwise, false.
    /// </returns>
    boolean validateWrite()
    {
        boolean isValid = next validateWrite();

        if (this.METAdvancedCalculation && this.METChargesMethod == METChargesMethod::None)
        {
            isValid = checkFailed("@MET:BlankChargeMethodNotAllowed");
        }

        return isValid;
    }

    /// <summary>
    /// Returns the calculation factor based on the advanced calculation and charge method.
    /// </summary>
    /// <returns>The calculated METCalculationFactor value.</returns>
    public display METCalculationFactor getCalculationFactor()
    {
        METCalculationFactor            calculationFactor;
        CustInvoiceJour                 custInvoiceJour = CustInvoiceJour::findRecId(this.TransRecId);
        CustInvoiceTrans                custInvoiceTrans;
        SalesLine                       salesLine;
        METSalesLine                    metSalesLine;
        METSalesOrderShipmentLoadLines  metSalesOrderShipmentLoadLines;
        MetContainerTable               metContainerTable;
        WHSContainerType                containerType;

        if(this.METAdvancedCalculation == NoYes::Yes
            && this.METChargesMethod != METChargesMethod::None
            && custInvoiceJour.RecId)
        {
            while select metSalesLine
            join salesLine
                where metSalesLine.SalesLine == salesLine.RecId
            join custInvoiceTrans
                where salesLine.InventTransId == custInvoiceTrans.InventTransId
                && custInvoiceTrans.SalesId == custInvoiceJour.SalesId
            {
                if(this.METChargesMethod == METChargesMethod::Weight)
                {
                    calculationFactor += metSalesLine.SalesUnitWeight;
                }
                else if(this.METChargesMethod == METChargesMethod::Volume)
                {
                    calculationFactor += metSalesLine.SalesUnitVolume;
                }              
            }   
 
            if(this.METChargesMethod == METChargesMethod::Pallet || this.METChargesMethod == METChargesMethod::SecurityCap)
            {
                METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader;

                METWHSContainerChargesMethod containerChargesMethod = this.METChargesMethod == METChargesMethod::Pallet ? METWHSContainerChargesMethod::ShrinkWrap : METWHSContainerChargesMethod::SecurityCap;

                SalesId orderNum = custInvoiceJour.SalesId;

                if (SalesTable::find(OrderNum).ReturnItemNum)
                {
                    orderNum = METSalesTable::findBySalesId(OrderNum).ClaimSalesId;
                }

                select sum(ContainerQty) from metContainerTable
                    where metContainerTable.OrderNum == orderNum
                    && metContainerTable.ContainerTypeCode == this.MarkupCode
                    exists join containerType
                    where containerType.METWHSContainerChargesMethod == containerChargesMethod
                       && containerType.ContainerTypeCode == metContainerTable.ContainerTypeCode
                    exists join salesOrderShipmentLoadHeader
                    where salesOrderShipmentLoadHeader.ShipmentId == metContainerTable.ShipmentId;

                calculationFactor = metContainerTable.ContainerQty;
            }
        }

        return calculationFactor;
    }

    /// <summary>
    /// COC extension of insert method.
    /// </summary>
    /// <param name="_targetAccountingStatus">
    /// The desired <c>SourceDocumentLineAccountingStatus</c>; optional.
    /// </param>
    public void insert(SourceDocumentLineAccountingStatus _targetAccountingStatus)
    {
        if (this.TransTableId == tableNum(PurchLine) || this.TransTableId == tableNum(VendInvoiceInfoLine))
        {
            MarkupTable markupTable;
            
            select firstonly RecId from markupTable
                where markupTable.MarkupCode == this.MarkupCode
                && markupTable.ModuleType == this.ModuleType
                && markupTable.CustType == MarkupType::LedgerAccount
                && markupTable.VendType == MarkupType::LedgerAccount;

                if (markupTable.RecId)
                {
                    this.TaxItemGroup = '';
                }
        }
        next insert(_targetAccountingStatus);
    }

    /// <summary>
    /// Update method extension to clear tax item group when the markup code is based on ledger account to avoid tax calculation issue.
    /// </summary>
    /// <param name = "_updateMiscMatching">boolean</param>
    /// <param name = "_isEditingBlockedByVendorInvoice">boolean</param>
    public void update(boolean _updateMiscMatching, boolean _isEditingBlockedByVendorInvoice)
    {
        _updateMiscMatching = true;
        _isEditingBlockedByVendorInvoice = this.isEditingBlockedByVendorInvoice();

        if (this.TransTableId == tableNum(PurchLine) || this.TransTableId == tableNum(VendInvoiceInfoLine))
        {
            MarkupTable markupTable;
            
            select firstonly RecId from markupTable
                where markupTable.MarkupCode == this.MarkupCode
                && markupTable.ModuleType == this.ModuleType
                && markupTable.CustType == MarkupType::LedgerAccount
                && markupTable.VendType == MarkupType::LedgerAccount;
                if (markupTable.RecId)
                {
                    this.TaxItemGroup = '';
                }
        }
        next update(_updateMiscMatching, _isEditingBlockedByVendorInvoice);
    }
